package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.collaboration.discussion.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class DiscussionStoreIntegrationTest {
 StudyStoreIntegrationTest parent;GroupStoreIntegrationTest f;DiscussionStore store;UUID group,space,study,author;
 @BeforeEach void setup(){parent=new StudyStoreIntegrationTest();parent.setup();f=parent.f;group=parent.group;space=parent.space;study=parent.create(f.key()).study().studyId();author=f.ids.next();store=new DiscussionStore(f.source,parent.store,Clock.systemUTC());}
 DiscussionStore.Result create(String key){return store.create(group,space,study,author,key,"토론 <script>","공유 원문\nDiscuss carefully",f.trace);}
 DiscussionStore.ReplyResult reply(UUID id,long expected,String key,String content){return store.reply(group,space,study,id,author,expected,key,content,f.trace);}
 void status(int code,org.junit.jupiter.api.function.Executable op){parent.status(code,op);}int events(UUID id){return parent.events(id);}
 @Test void sharedTopicRevisionAndOutboxSnapshotCommitTogether()throws Exception{
  var v=create(f.key()).discussion();assertEquals(7,v.discussionId().version());assertEquals("OPEN",v.state());assertEquals("GROUP_MEMBERS",v.audience());assertEquals(author,v.creatorId());assertEquals(v,store.get(group,space,study,v.discussionId()));assertEquals(v,store.history(group,space,study,v.discussionId(),Long.MAX_VALUE,5).items().getFirst().snapshot());
  var e=DiscussionEnvelopeV1.parseFrom(f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.discussionId()));var p=DiscussionSnapshotV1.parseFrom(e.getPayload());assertEquals("DiscussionCreated",e.getEventType());assertEquals("Discussion",e.getAggregateType());assertEquals(v.discussionId().toString(),e.getAggregateId());assertEquals(author.toString(),e.getActorId());assertEquals(f.trace,e.getTraceId());assertEquals(space.toString(),e.getSpaceId());assertEquals(study.toString(),p.getStudyId());assertEquals(v.description(),p.getDescription());assertEquals("GROUP_MEMBERS",p.getAudience());assertEquals(1,parent.store.get(group,space,study).version());
 }
 @Test void replyIsImmutableSeparateAggregateWithPinnedDiscussionVersion()throws Exception{
  var d=create(f.key()).discussion();var r=reply(d.discussionId(),1,f.key(),"Reply <img src=x>").reply();assertEquals(7,r.replyId().version());assertEquals(1,r.version());assertEquals(1,r.discussionVersion());assertEquals(author,r.authorId());assertEquals(r,store.getReply(group,space,study,d.discussionId(),r.replyId()));assertEquals(1,store.get(group,space,study,d.discussionId()).version());assertEquals(1,events(d.discussionId()));
  var e=DiscussionEnvelopeV1.parseFrom(f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,r.replyId()));var p=DiscussionReplySnapshotV1.parseFrom(e.getPayload());assertEquals("DiscussionReplyCreated",e.getEventType());assertEquals("DiscussionReply",e.getAggregateType());assertEquals(r.replyId().toString(),e.getAggregateId());assertEquals(r.content(),p.getContent());assertEquals(d.discussionId().toString(),p.getDiscussionId());assertEquals("GROUP_MEMBERS",p.getAudience());assertEquals(1,p.getVersion());
 }
 @Test void exactCreateAndReplyRetriesSurviveStateChangesParentArchiveAndRestart(){
  String key=f.key(),replyKey=f.key();var d=create(key).discussion();var r=reply(d.discussionId(),1,replyKey,"Original reply").reply();var locked=store.state(group,space,study,d.discussionId(),f.owner,1,"LOCKED",f.trace);assertEquals(locked,create(key).discussion());status(409,()->store.create(group,space,study,author,key,"Changed","",f.trace));status(409,()->reply(d.discussionId(),1,replyKey,"Changed reply"));status(409,()->reply(d.discussionId(),2,replyKey,"Original reply"));var retired=store.state(group,space,study,d.discussionId(),f.owner,2,"RETIRED",f.trace);parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);
  var restarted=new DiscussionStore(f.source,parent.store,Clock.systemUTC());var again=restarted.create(group,space,study,author,key,d.title(),d.description(),f.trace);assertFalse(again.created());assertEquals(retired,again.discussion());var retry=restarted.reply(group,space,study,d.discussionId(),author,1,replyKey,"Original reply",f.trace);assertFalse(retry.created());assertEquals(r,retry.reply());assertEquals(1,events(r.replyId()));assertEquals(3,events(d.discussionId()));status(409,()->create(f.key()));
 }
 @Test void lockUnlockArchiveAndStrongVersionsProtectModerationAndReplies(){
  var d=create(f.key()).discussion();var locked=store.state(group,space,study,d.discussionId(),f.owner,1,"LOCKED",f.trace);assertEquals(locked,store.state(group,space,study,d.discussionId(),f.owner,2,"LOCKED",f.trace));assertEquals(2,events(d.discussionId()));status(412,()->store.state(group,space,study,d.discussionId(),f.owner,1,"OPEN",f.trace));status(409,()->reply(d.discussionId(),2,f.key(),"Locked"));store.state(group,space,study,d.discussionId(),f.owner,2,"OPEN",f.trace);status(412,()->reply(d.discussionId(),1,f.key(),"Stale context"));var r=reply(d.discussionId(),3,f.key(),"After reopening").reply();assertEquals(3,r.discussionVersion());var retired=store.state(group,space,study,d.discussionId(),f.owner,3,"RETIRED",f.trace);assertEquals(retired,store.state(group,space,study,d.discussionId(),f.owner,4,"RETIRED",f.trace));status(409,()->store.state(group,space,study,d.discussionId(),f.owner,4,"OPEN",f.trace));status(409,()->reply(d.discussionId(),4,f.key(),"Archived"));assertEquals(r,store.getReply(group,space,study,d.discussionId(),r.replyId()));
 }
 @Test void archivedStudyFreezesOpenDiscussionWithoutHidingOriginalText(){
  var d=create(f.key()).discussion();var r=reply(d.discussionId(),1,f.key(),"Before archive").reply();parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);assertTrue(store.list(group,space,study,null,20).studyArchived());assertEquals(d,store.get(group,space,study,d.discussionId()));assertEquals(r,store.replies(group,space,study,d.discussionId(),null,5).items().getFirst());status(409,()->create(f.key()));status(409,()->reply(d.discussionId(),1,f.key(),"After archive"));status(409,()->store.state(group,space,study,d.discussionId(),f.owner,1,"LOCKED",f.trace));assertEquals(1,events(d.discussionId()));
 }
 @Test void scopedCatalogReplyAndHistoryPaginationNeverCrossParents(){
  var d=create(f.key()).discussion();create(f.key());create(f.key());var page=store.list(group,space,study,null,2);assertEquals(2,page.items().size());assertNotNull(page.nextAfter());assertEquals(1,store.list(group,space,study,page.nextAfter(),2).items().size());var replies=new ArrayList<DiscussionStore.Reply>();for(int n=0;n<3;n++)replies.add(reply(d.discussionId(),1,f.key(),"Reply "+n).reply());var p=store.replies(group,space,study,d.discussionId(),null,2);assertEquals(2,p.items().size());assertEquals(List.of(replies.get(2)),store.replies(group,space,study,d.discussionId(),p.nextAfter(),2).items());
  status(404,()->store.get(group,f.owner,study,d.discussionId()));status(404,()->store.get(f.owner,space,study,d.discussionId()));status(404,()->store.get(group,space,f.owner,d.discussionId()));status(404,()->store.replies(group,space,f.owner,d.discussionId(),null,5));status(404,()->store.getReply(group,space,f.owner,d.discussionId(),replies.getFirst().replyId()));status(404,()->store.getReply(group,space,study,f.owner,replies.getFirst().replyId()));
  store.state(group,space,study,d.discussionId(),f.owner,1,"LOCKED",f.trace);store.state(group,space,study,d.discussionId(),f.owner,2,"OPEN",f.trace);var h=store.history(group,space,study,d.discussionId(),Long.MAX_VALUE,2);assertEquals(List.of(3L,2L),h.items().stream().map(DiscussionStore.Revision::version).toList());assertEquals(1,store.history(group,space,study,d.discussionId(),h.nextBefore(),2).items().size());
 }
 @Test void concurrentCreationReplyRetriesAndModerationEachHaveOneWinner()throws Exception{
  try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);String key=f.key();var a=pool.submit(()->{barrier.await();return create(key);});var b=pool.submit(()->{barrier.await();return create(key);});var x=a.get();var y=b.get();assertNotEquals(x.created(),y.created());assertEquals(x.discussion(),y.discussion());String rk=f.key();var ra=pool.submit(()->{barrier.await();return reply(x.discussion().discussionId(),1,rk,"Same reply");});var rb=pool.submit(()->{barrier.await();return reply(x.discussion().discussionId(),1,rk,"Same reply");});var rx=ra.get();var ry=rb.get();assertNotEquals(rx.created(),ry.created());assertEquals(rx.reply(),ry.reply());assertEquals(1,events(rx.reply().replyId()));
   var results=new ArrayList<Future<Boolean>>();for(String state:List.of("LOCKED","RETIRED"))results.add(pool.submit(()->{barrier.await();try{store.state(group,space,study,x.discussion().discussionId(),f.owner,1,state,f.trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(results.get(0).get(),results.get(1).get());assertEquals(2,events(x.discussion().discussionId()));
  }
 }
 @Test void lockAndReplySerializeOnParentDiscussion()throws Exception{
  var d=create(f.key()).discussion();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return store.state(group,space,study,d.discussionId(),f.owner,1,"LOCKED",f.trace);});var b=pool.submit(()->{barrier.await();try{return reply(d.discussionId(),1,f.key(),"Concurrent reply").reply();}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals("LOCKED",a.get().state());var result=b.get();assertEquals(result==null?0:1,store.replies(group,space,study,d.discussionId(),null,5).items().size());status(409,()->reply(d.discussionId(),2,f.key(),"After lock"));}
 }
 @Test void failedOutboxRollsBackCreationStateRevisionAndReply(){
  String name="discussion_fail_"+study.toString().replace("-","");String check=" CHECK (aggregatetype NOT IN ('discussion','discussion-reply') OR trace_id <> '"+f.trace+"') NOT VALID";f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->create(f.key()));assertTrue(store.list(group,space,study,null,20).items().isEmpty());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var d=create(f.key()).discussion();f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->store.state(group,space,study,d.discussionId(),f.owner,1,"LOCKED",f.trace));assertThrows(RuntimeException.class,()->reply(d.discussionId(),1,f.key(),"Rollback"));assertEquals(d,store.get(group,space,study,d.discussionId()));assertEquals(1,store.history(group,space,study,d.discussionId(),Long.MAX_VALUE,5).items().size());assertTrue(store.replies(group,space,study,d.discussionId(),null,5).items().isEmpty());assertEquals(1,events(d.discussionId()));}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}
 }
}
